# Initially generated by GitHub Copilot.

import unittest

import main_tmpl_survey
from tmpl_survey import nesting_normal_form as nnf


class TestTmplSurveyNestingNormalForm(unittest.TestCase):
    def test_plus_e_uses_custom_rank_overrides(self):
        case_rank_maps = main_tmpl_survey._case_rank_maps(
            main_tmpl_survey._default_case_rank_groups()
        )

        plus_e = case_rank_maps["plus-E"]
        self.assertEqual(plus_e["כו״ק"], plus_e["מ:כו״ק מיוחד"])
        self.assertEqual(plus_e["כו״ק"], plus_e["מ:קו״כ-אם-2"])
        self.assertEqual(plus_e["כו״ק"], plus_e["קו״כ"])
        self.assertEqual(plus_e["מ:דחי"], plus_e["מ:הערה-2"])

        plain_e = case_rank_maps["plain-E"]
        self.assertNotIn("מ:כו״ק מיוחד", plain_e)
        self.assertNotIn("מ:קו״כ-אם-2", plain_e)
        self.assertNotIn("קו״כ", plain_e)
        self.assertNotIn("מ:הערה-2", plain_e)

    def test_regex_like_grammar_shape(self):
        self.assertEqual(
            "rank-1?rank-2?rank-3?rank-4?rank-5?rank-6?",
            nnf.regex_like_grammar(),
        )

    def test_allows_strictly_increasing_rank_order(self):
        stack_counts = {
            ("מ:אות-מיוחדת-במילה", "E/מ:כפול/נוסח/כו״ק/מ:קמץ/מ:דחי"): 2,
        }
        nnf.assert_stack_counts_in_normal_form(stack_counts, dataset_name="unit")

    def test_ignores_unranked_templates_between_ranked_templates(self):
        stack_counts = {
            ("מ:דחי", "E/מ:הערה-2/מ:קמץ"): 4,
        }
        nnf.assert_stack_counts_in_normal_form(stack_counts, dataset_name="unit")

    def test_rejects_descending_rank_transition(self):
        stack_counts = {
            ("מ:קמץ", "E/מ:דחי"): 3,
        }
        with self.assertRaises(AssertionError) as ctx:
            nnf.assert_stack_counts_in_normal_form(stack_counts, dataset_name="unit")
        self.assertIn("מ:דחי (rank 4) -> מ:קמץ (rank 3)", str(ctx.exception))
        self.assertIn("relation=descending", str(ctx.exception))

    def test_rejects_duplicate_rank_transition(self):
        stack_counts = {
            ("כו״ק", "E/כתיב ולא קרי"): 3,
        }
        with self.assertRaises(AssertionError) as ctx:
            nnf.assert_stack_counts_in_normal_form(stack_counts, dataset_name="unit")
        self.assertIn("כתיב ולא קרי (rank 2) -> כו״ק (rank 2)", str(ctx.exception))
        self.assertIn("relation=duplicate-rank", str(ctx.exception))

    def test_aggregates_violation_counts(self):
        stack_counts = {
            ("מ:קמץ", "E/מ:דחי"): 3,
            ("מ:קמץ", "D/נוסח/מ:דחי"): 5,
        }
        violations = nnf.find_rank_violations(stack_counts)
        self.assertEqual(1, len(violations))
        self.assertEqual("מ:דחי", violations[0]["caller"])
        self.assertEqual("מ:קמץ", violations[0]["callee"])
        self.assertEqual("descending", violations[0]["relation"])
        self.assertEqual(4, violations[0]["caller_rank"])
        self.assertEqual(3, violations[0]["callee_rank"])
        self.assertEqual(8, violations[0]["count"])

    def test_aggregates_duplicate_rank_violation_counts(self):
        stack_counts = {
            ("כו״ק", "E/כתיב ולא קרי"): 3,
            ("כו״ק", "D/נוסח/כתיב ולא קרי"): 5,
        }
        violations = nnf.find_rank_violations(stack_counts)
        self.assertEqual(1, len(violations))
        self.assertEqual("כתיב ולא קרי", violations[0]["caller"])
        self.assertEqual("כו״ק", violations[0]["callee"])
        self.assertEqual("duplicate-rank", violations[0]["relation"])
        self.assertEqual(2, violations[0]["caller_rank"])
        self.assertEqual(2, violations[0]["callee_rank"])
        self.assertEqual(8, violations[0]["count"])

    def test_case_rank_maps_allow_per_column_configuration(self):
        stack_counts = {
            ("B", "C/A"): 1,
            ("B", "D/A"): 1,
            ("B", "E/A"): 1,
        }
        same_order = nnf.build_rank_map((
            ("rank-1", ("A",)),
            ("rank-2", ("B",)),
        ))
        case_rank_maps = {
            "plain-C": same_order,
            "plain-D": same_order,
            "plain-E": same_order,
        }
        nnf.assert_stack_counts_in_normal_form_by_case(
            stack_counts,
            dataset_key="plain",
            case_rank_maps=case_rank_maps,
        )

    def test_case_rank_maps_can_fail_one_column_only(self):
        stack_counts = {
            ("B", "C/A"): 1,
            ("B", "D/A"): 1,
            ("B", "E/A"): 1,
        }
        a_before_b = nnf.build_rank_map((
            ("rank-1", ("A",)),
            ("rank-2", ("B",)),
        ))
        b_before_a = nnf.build_rank_map((
            ("rank-1", ("B",)),
            ("rank-2", ("A",)),
        ))
        case_rank_maps = {
            "plain-C": a_before_b,
            "plain-D": a_before_b,
            "plain-E": b_before_a,
        }
        with self.assertRaises(AssertionError) as ctx:
            nnf.assert_stack_counts_in_normal_form_by_case(
                stack_counts,
                dataset_key="plain",
                case_rank_maps=case_rank_maps,
            )
        self.assertIn("plain survey (E column)", str(ctx.exception))

    def test_case_rank_maps_require_all_dataset_columns(self):
        stack_counts = {
            ("B", "C/A"): 1,
        }
        case_rank_maps = {
            "plus-C": nnf.build_rank_map(
                (("rank-1", ("A",)), ("rank-2", ("B",)))
            ),
            "plus-D": nnf.build_rank_map(
                (("rank-1", ("A",)), ("rank-2", ("B",)))
            ),
        }
        with self.assertRaises(ValueError) as ctx:
            nnf.assert_stack_counts_in_normal_form_by_case(
                stack_counts,
                dataset_key="plus",
                case_rank_maps=case_rank_maps,
            )
        self.assertIn("plus-E", str(ctx.exception))

    def test_summarize_rank_coverage_counts_classifies_cov_buckets(self):
        rank_map = nnf.build_rank_map((
            ("rank-1", ("A",)),
            ("rank-2", ("B",)),
            ("rank-3", ("C",)),
        ))
        stack_counts = {
            # full template path A/B/C => cov=1
            ("C", "C/A/B"): 2,
            # full template path A/X/C => 0<cov<1
            ("C", "C/A/X"): 3,
            # full template path X/Y/Z => cov=0
            ("Z", "C/X/Y"): 5,
        }
        summary = nnf.summarize_rank_coverage_counts(stack_counts, rank_map)
        self.assertEqual(
            {
                "fully_checked": 2,
                "partially_checked": 3,
                "totally_unchecked": 5,
                "total": 10,
            },
            summary,
        )

    def test_summarize_rank_coverage_by_case_returns_dataset_case_keys(self):
        stack_counts = {
            ("B", "C/A"): 1,
            ("B", "D/A"): 1,
            ("Z", "E/X"): 1,
        }
        a_before_b = nnf.build_rank_map((
            ("rank-1", ("A",)),
            ("rank-2", ("B",)),
        ))
        case_rank_maps = {
            "plain-C": a_before_b,
            "plain-D": a_before_b,
            "plain-E": a_before_b,
        }

        summary = nnf.summarize_rank_coverage_by_case(
            stack_counts,
            dataset_key="plain",
            case_rank_maps=case_rank_maps,
        )

        self.assertEqual({"plain-C", "plain-D", "plain-E"}, set(summary))
        self.assertEqual(1, summary["plain-C"]["fully_checked"])
        self.assertEqual(1, summary["plain-D"]["fully_checked"])
        self.assertEqual(1, summary["plain-E"]["totally_unchecked"])

    def test_infer_expanded_stack_grammar_has_edges_and_order(self):
        baseline = {
            ("C", "R/A/B"): 2,
            ("X", "R/C"): 1,
            ("A", "R/X"): 1,
        }
        grammar = nnf.infer_expanded_stack_grammar(baseline)

        self.assertEqual("expanded-stack-grammar-v1", grammar["version"])
        self.assertIn(["R", "A"], grammar["allowed_edges"])
        self.assertIn(["A", "B"], grammar["allowed_edges"])
        self.assertIn(["B", "C"], grammar["allowed_edges"])
        self.assertIn(["A", "C"], grammar["must_precede"])

    def test_expanded_stack_grammar_allows_unseen_but_consistent_stack(self):
        baseline = {
            ("C", "R/A/B"): 2,
            ("X", "R/C"): 1,
            ("A", "R/X"): 1,
        }
        grammar = nnf.infer_expanded_stack_grammar(baseline)
        candidate = {
            ("B", "R/A"): 1,
        }
        nnf.assert_stack_counts_follow_expanded_grammar(
            candidate,
            grammar,
            dataset_name="unit-candidate",
        )

    def test_expanded_stack_grammar_rejects_permutation(self):
        baseline = {
            ("C", "R/A/B"): 2,
            ("X", "R/C"): 1,
            ("A", "R/X"): 1,
        }
        grammar = nnf.infer_expanded_stack_grammar(baseline)

        # This path uses known edges (R->C, C->X, X->A) but reverses
        # the baseline order constraint A before C.
        candidate = {
            ("A", "R/C/X"): 1,
        }
        with self.assertRaises(AssertionError) as ctx:
            nnf.assert_stack_counts_follow_expanded_grammar(
                candidate,
                grammar,
                dataset_name="unit-candidate",
            )
        msg = str(ctx.exception)
        self.assertIn("order-permutation", msg)
        self.assertIn("expected A before C", msg)

    def test_expanded_stack_grammar_detects_unexpected_edge(self):
        baseline = {
            ("C", "R/A/B"): 2,
        }
        grammar = nnf.infer_expanded_stack_grammar(baseline)
        candidate = {
            ("B", "R/C"): 1,
        }
        violations = nnf.find_expanded_grammar_violations(candidate, grammar)
        edge_violations = [v for v in violations if v["kind"] == "unexpected-edge"]
        self.assertTrue(edge_violations)
        self.assertIn(
            ("R", "C"),
            {(v["parent"], v["child"]) for v in edge_violations},
        )

    def test_merge_stack_counts_sums_shared_keys(self):
        first = {("A", "R"): 2, ("B", "R/A"): 3}
        second = {("A", "R"): 5, ("C", "R/A/B"): 7}
        merged = nnf.merge_stack_counts(first, second)
        self.assertEqual(7, merged[("A", "R")])
        self.assertEqual(3, merged[("B", "R/A")])
        self.assertEqual(7, merged[("C", "R/A/B")])


if __name__ == "__main__":
    unittest.main()
